function kept(source: string): string | null {
  const node = sanitizeSvg(source);
  return node === null ? null : canonicalSvg(node);
}

describe('svgDocument keeps what the shared allow-list keeps', () => {
  for (const { source, output } of SANITIZE_CASES) {
    it(`draws ${JSON.stringify(output)} for ${JSON.stringify(source)}`, () => {
      expect(kept(source)).toBe(output);
    });
  }
});

describe('svgDocument draws the kept tree as SVG elements', () => {
  it('builds SVG elements, with a kept style applied through the CSS object model', () => {
    const node = sanitizeSvg(
      `<svg xmlns="${SVG_NAMESPACE}"><rect style="fill: #0a0" width="4"/><script>alert(1)</script></svg>`,
    );
    expect(node).not.toBeNull();
    const root = drawSvg(node!, document);
    expect(root.namespaceURI).toBe(SVG_NAMESPACE);
    expect(root.querySelector('script')).toBeNull();
    const rect = root.firstElementChild as SVGElement;
    expect(rect.localName).toBe('rect');
    expect(rect.namespaceURI).toBe(SVG_NAMESPACE);
    expect(rect.getAttribute('width')).toBe('4');
    expect(rect.style.getPropertyValue('fill')).not.toBe('');
  });

  it('reads a Bytes field as the UTF-8 markup it holds and refuses bytes that are no UTF-8', async () => {
    expect(await svgMarkupOf(btoa('<svg/>'))).toBe('<svg/>');
    await expect(svgMarkupOf(new Blob([new Uint8Array([0xff, 0xfe, 0xfd])]))).rejects.toThrow();
  });
});

describe('svgDocument zoom and pan', () => {
  const whole = { x: 0, y: 0, width: 100, height: 50 };

  it('reads the whole drawing from its viewBox, else its width and height', () => {
    expect(svgBoxOf(sanitizeSvg('<svg viewBox="0 0 100 50"/>')!)).toEqual(whole);
    expect(svgBoxOf(sanitizeSvg('<svg width="100px" height="50"/>')!)).toEqual(whole);
    expect(svgBoxOf(sanitizeSvg('<svg width="10em" height="5em"/>')!)).toBeNull();
  });

  it('opens on the whole drawing and never zooms out past it', () => {
    const view = new UiSvgView();
    view.show(whole);
    expect(view.viewBox()).toBe('0 0 100 50');
    view.zoomOut();
    expect(view.zoom()).toBe(1);
    expect(view.canZoomOut()).toBe(false);
  });

  it('zooms in up to its limit, keeping the point it zooms at in place', () => {
    const view = new UiSvgView();
    view.show(whole);
    view.zoomBy(2, { x: 0, y: 0 });
    expect(view.box()).toEqual({ x: 0, y: 0, width: 50, height: 25 });
    for (let step = 0; step < 40; step += 1) {
      view.zoomIn();
    }
    expect(view.zoom()).toBe(SVG_MAX_ZOOM);
    expect(view.canZoomIn()).toBe(false);
  });

  it('pans within the drawing and resets to the whole of it', () => {
    const view = new UiSvgView();
    view.show(whole);
    view.zoomBy(SVG_ZOOM_STEP * SVG_ZOOM_STEP);
    view.panBy(1000, 1000);
    const box = view.box()!;
    expect(box.x + box.width).toBeCloseTo(100);
    expect(box.y + box.height).toBeCloseTo(50);
    view.reset();
    expect(view.isWhole()).toBe(true);
    expect(view.viewBox()).toBe('0 0 100 50');
  });

  it('cannot zoom a drawing that states no box', () => {
    const view = new UiSvgView();
    view.show(null);
    view.zoomIn();
    expect(view.canZoomIn()).toBe(false);
    expect(view.viewBox()).toBeNull();
  });
});
